import{_ as t,o as a,c as r,ao as o}from"./chunks/framework.DqWL2xRk.js";const p=JSON.parse('{"title":"Moving older R code to DRModels.jl","description":"","frontmatter":{},"headers":[],"relativePath":"reference/deprecated-marker-internals.md","filePath":"reference/deprecated-marker-internals.md","lastUpdated":null}'),d={name:"reference/deprecated-marker-internals.md"};function n(l,e,s,i,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="Moving-older-R-code-to-DRModels.jl" tabindex="-1">Moving older R code to DRModels.jl <a class="header-anchor" href="#Moving-older-R-code-to-DRModels.jl" aria-label="Permalink to &quot;Moving older R code to DRModels.jl {#Moving-older-R-code-to-DRModels.jl}&quot;">​</a></h1><p>If you are translating an older <code>drmTMB</code> analysis, use the modern spelling in the table below. DRModels.jl does not carry the retired R names.</p><h2 id="Deprecation-map" tabindex="-1">Deprecation map <a class="header-anchor" href="#Deprecation-map" aria-label="Permalink to &quot;Deprecation map {#Deprecation-map}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">drmTMB (deprecated)</th><th style="text-align:right;">Use instead in DRModels.jl</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>meta_known_V(V)</code></td><td style="text-align:right;"><code>meta_V(v)</code></td><td style="text-align:right;">Meta-analysis with known sampling (co)variances. The modern spelling is <code>meta_V</code>, attached to a <code>Gaussian()</code> model: <code>drm(bf(y ~ meta_V(v)), Gaussian(); data = …)</code>.</td></tr><tr><td style="text-align:right;"><code>gr(…)</code></td><td style="text-align:right;">(no equivalent needed)</td><td style="text-align:right;">This R helper has no user-facing Julia equivalent.</td></tr></tbody></table><h2 id="Why-the-older-names-are-not-available" tabindex="-1">Why the older names are not available <a class="header-anchor" href="#Why-the-older-names-are-not-available" aria-label="Permalink to &quot;Why the older names are not available {#Why-the-older-names-are-not-available}&quot;">​</a></h2><p>drmTMB keeps <code>meta_known_V</code> / <code>gr</code> only as deprecated shims for backward compatibility with older R scripts. DRModels.jl is a fresh Julia API, so it exposes <strong>only the current names</strong> — there is no legacy surface to preserve. If you are translating an R script that calls <code>meta_known_V</code>, replace it with <code>meta_V</code>; the arguments (the known sampling variances) carry over directly.</p><p>For the meta-analysis workflow itself, see the meta-analysis tutorial and the <code>meta_V</code> entry in the structured-effect markers reference.</p>',7)])])}const g=t(d,[["render",n]]);export{p as __pageData,g as default};
